insert into public.protocols (id, slug, title, description, objective, long_description, category, category_label, duration, level, benefits, steps, is_premium, featured, tag, participants, cover_image_url, content, seo_title, seo_description, seo_keywords, og_image_url, status) values ('71000002-0002-4002-8002-000000000001', 'sono-restaurador', 'Sono Restaurador', 'Protocolo premium de 21 dias para regular o ritmo circadiano, aprofundar o sono e acordar com energia real — sem depender de estimulantes.', 'Restaurar a qualidade do sono com rotinas noturnas estruturadas, otimização do ambiente e hábitos diurnos que sustentam o descanso profundo.', 'Um plano progressivo que combina higiene do sono, gestão de luz e temperatura, alimentação estratégica e técnicas de relaxamento para noites consistentemente reparadoras.', 'sono', 'Sono', '21 dias', 'Intermediário', '["Adormecer em menos tempo","Sono mais profundo e contínuo","Mais disposição ao acordar","Humor e foco mais estáveis","Menos dependência de cafeína"]'::jsonb, '[{"title":"Dias 1–7","description":"Mapeamento do ritmo, horários fixos e redução de estimulantes."},{"title":"Dias 8–14","description":"Otimização do ambiente e rotina noturna estruturada."},{"title":"Dias 15–21","description":"Consolidação, ajustes finos e plano de manutenção."}]'::jsonb, true, true, 'Premium', 420, '/blog/categories/sono.svg', '[{"type":"image","url":"/blog/categories/sono.svg","alt":"Capa: Sono Restaurador"},{"type":"heading","level":2,"text":"Objetivo"},{"type":"paragraph","text":"Restaurar a qualidade do sono com rotinas noturnas estruturadas, otimização do ambiente e hábitos diurnos que sustentam o descanso profundo."},{"type":"heading","level":2,"text":"Duração"},{"type":"paragraph","text":"21 dias · Nível Intermediário. Siga o roteiro diário com constância; ajustes finos são esperados conforme sua rotina."},{"type":"heading","level":2,"text":"Passo a passo diário"},{"type":"list","items":["Acordar no mesmo horário (±30 min), mesmo nos fins de semana.","Expor-se à luz natural nos primeiros 30 minutos após acordar.","Evitar cafeína após 14h; hidratar-se ao longo do dia.","Realizar movimento leve até 18h (caminhada, alongamento ou yoga).","Jantar leve 3 horas antes de deitar; reduzir telas 90 min antes.","Preparar o quarto: escuro, fresco (18–20 °C) e silencioso.","Rotina de desaceleração: respiração 4-7-8, leitura ou journaling.","Deitar apenas quando sentir sonolência; levantar se não dormir em 20 min."],"ordered":true},{"type":"heading","level":2,"text":"Checklist diária"},{"type":"list","items":["Horário fixo de despertar","Luz solar matinal","Sem cafeína após 14h","Movimento leve no dia","Jantar leve e cedo","Telas reduzidas à noite","Quarto escuro e fresco","Rotina de relaxamento"]},{"type":"heading","level":2,"text":"Benefícios esperados"},{"type":"list","items":["Adormecer em menos tempo","Sono mais profundo e contínuo","Mais disposição ao acordar","Humor e foco mais estáveis","Menos dependência de cafeína"]},{"type":"heading","level":2,"text":"Continue no Clube Premium"},{"type":"paragraph","html":"<p>Este protocolo faz parte do <strong>Clube Saúde &amp; Bem Premium</strong>. Assine para acessar o passo a passo completo, checklist imprimível e acompanhamento na sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'Sono Restaurador | Protocolo Premium Saúde & Bem', 'Protocolo premium de 21 dias para regular o ritmo circadiano, aprofundar o sono e acordar com energia real — sem depender de estimulantes.', 'sono, restaurador, sono, protocolo, premium, saúde e bem', '/blog/categories/sono.svg', 'published');
insert into public.protocols (id, slug, title, description, objective, long_description, category, category_label, duration, level, benefits, steps, is_premium, featured, tag, participants, cover_image_url, content, seo_title, seo_description, seo_keywords, og_image_url, status) values ('71000002-0002-4002-8002-000000000002', 'energia-diaria-premium', 'Energia Diária', 'Rotina premium de 14 dias para energia estável do acordar ao fim do dia — sem picos artificiais nem queda vespertina.', 'Construir um ritmo circadiano alinhado com alimentação estratégica, movimento e pausas que sustentam foco e vitalidade o dia inteiro.', 'Versão avançada do protocolo de energia: inclui janelas de alimentação, exposição à luz, micro-hábitos de recuperação e gestão de estimulantes.', 'energia', 'Energia', '14 dias', 'Iniciante', '["Energia estável sem picos e quedas","Foco prolongado na parte da tarde","Menos fadiga mental","Melhor qualidade de sono","Produtividade sustentável"]'::jsonb, '[{"title":"Dias 1–5","description":"Ritmo matinal, hidratação e primeiros blocos de foco."},{"title":"Dias 6–10","description":"Alimentação energizante e pausas estratégicas."},{"title":"Dias 11–14","description":"Rotina personalizada e plano de manutenção."}]'::jsonb, true, true, 'Premium', 457, '/logo-saude-bem.png', '[{"type":"image","url":"/logo-saude-bem.png","alt":"Capa: Energia Diária"},{"type":"heading","level":2,"text":"Objetivo"},{"type":"paragraph","text":"Construir um ritmo circadiano alinhado com alimentação estratégica, movimento e pausas que sustentam foco e vitalidade o dia inteiro."},{"type":"heading","level":2,"text":"Duração"},{"type":"paragraph","text":"14 dias · Nível Iniciante. Siga o roteiro diário com constância; ajustes finos são esperados conforme sua rotina."},{"type":"heading","level":2,"text":"Passo a passo diário"},{"type":"list","items":["Acordar com hidratação (500 ml água + pitada de sal ou limão).","Exposição solar 10–15 min + alongamento de 5 min.","Café da manhã com proteína, gordura boa e fibras.","Bloco de foco de 90 min sem interrupções (modo avião).","Pausa ativa: caminhada de 10 min ou mobilidade.","Almoço equilibrado; evitar excesso de carboidratos refinados.","Pausa vespertina: respiração ou cochilo power de 15–20 min (se possível).","Encerrar o dia com movimento leve e jantar leve 3h antes de dormir."],"ordered":true},{"type":"heading","level":2,"text":"Checklist diária"},{"type":"list","items":["Hidratação matinal","Luz solar + movimento","Café da manhã proteico","Bloco de foco profundo","Pausa ativa no meio do dia","Almoço equilibrado","Recuperação vespertina","Encerramento consciente"]},{"type":"heading","level":2,"text":"Benefícios esperados"},{"type":"list","items":["Energia estável sem picos e quedas","Foco prolongado na parte da tarde","Menos fadiga mental","Melhor qualidade de sono","Produtividade sustentável"]},{"type":"heading","level":2,"text":"Continue no Clube Premium"},{"type":"paragraph","html":"<p>Este protocolo faz parte do <strong>Clube Saúde &amp; Bem Premium</strong>. Assine para acessar o passo a passo completo, checklist imprimível e acompanhamento na sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'Energia Diária | Protocolo Premium Saúde & Bem', 'Rotina premium de 14 dias para energia estável do acordar ao fim do dia — sem picos artificiais nem queda vespertina.', 'energia, diaria, premium, energia, protocolo, premium, saúde e bem', '/logo-saude-bem.png', 'published');
insert into public.protocols (id, slug, title, description, objective, long_description, category, category_label, duration, level, benefits, steps, is_premium, featured, tag, participants, cover_image_url, content, seo_title, seo_description, seo_keywords, og_image_url, status) values ('71000002-0002-4002-8002-000000000003', 'reducao-estresse', 'Redução do Estresse', 'Protocolo de 14 dias com técnicas de regulação do sistema nervoso para reduzir tensão, ansiedade leve e sobrecarga mental.', 'Desenvolver um kit diário de ferramentas — respiração, mindfulness, movimento e limites — para responder ao estresse com mais calma e clareza.', 'Abordagem integrada que combina práticas de respiração, journaling, movimento suave e higiene digital para restaurar equilíbrio emocional.', 'controle-estresse', 'Controle do Estresse', '14 dias', 'Iniciante', '["Menos tensão muscular e mental","Melhor regulação emocional","Sono mais tranquilo","Maior clareza nas decisões","Resiliência ao longo do dia"]'::jsonb, '[{"title":"Dias 1–4","description":"Consciência corporal e respiração base."},{"title":"Dias 5–10","description":"Ferramentas de regulação e limites digitais."},{"title":"Dias 11–14","description":"Consolidação e plano anti-recaída."}]'::jsonb, true, true, 'Premium', 494, '/logo-saude-bem.png', '[{"type":"image","url":"/logo-saude-bem.png","alt":"Capa: Redução do Estresse"},{"type":"heading","level":2,"text":"Objetivo"},{"type":"paragraph","text":"Desenvolver um kit diário de ferramentas — respiração, mindfulness, movimento e limites — para responder ao estresse com mais calma e clareza."},{"type":"heading","level":2,"text":"Duração"},{"type":"paragraph","text":"14 dias · Nível Iniciante. Siga o roteiro diário com constância; ajustes finos são esperados conforme sua rotina."},{"type":"heading","level":2,"text":"Passo a passo diário"},{"type":"list","items":["Manhã: 5 min de respiração diafragmática (4-4-6 ou box breathing).","Identificar 1 gatilho de estresse e definir resposta alternativa.","Pausa mindful de 3 min antes do almoço (atenção à respiração).","Caminhada ao ar livre de 15 min sem celular.","Tarde: journaling de 5 linhas (o que sinto / o que preciso).","Limitar notificações em 2 blocos de 30 min no dia.","Noite: relaxamento progressivo muscular (10 min).","Gratidão: anotar 3 coisas positivas do dia."],"ordered":true},{"type":"heading","level":2,"text":"Checklist diária"},{"type":"list","items":["Respiração matinal","Gatilho mapeado","Pausa mindful","Caminhada sem telas","Journaling","Limites digitais","Relaxamento noturno","Gratidão"]},{"type":"heading","level":2,"text":"Benefícios esperados"},{"type":"list","items":["Menos tensão muscular e mental","Melhor regulação emocional","Sono mais tranquilo","Maior clareza nas decisões","Resiliência ao longo do dia"]},{"type":"heading","level":2,"text":"Continue no Clube Premium"},{"type":"paragraph","html":"<p>Este protocolo faz parte do <strong>Clube Saúde &amp; Bem Premium</strong>. Assine para acessar o passo a passo completo, checklist imprimível e acompanhamento na sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'Redução do Estresse | Protocolo Premium Saúde & Bem', 'Protocolo de 14 dias com técnicas de regulação do sistema nervoso para reduzir tensão, ansiedade leve e sobrecarga mental.', 'reducao, estresse, controle estresse, protocolo, premium, saúde e bem', '/logo-saude-bem.png', 'published');
insert into public.protocols (id, slug, title, description, objective, long_description, category, category_label, duration, level, benefits, steps, is_premium, featured, tag, participants, cover_image_url, content, seo_title, seo_description, seo_keywords, og_image_url, status) values ('71000002-0002-4002-8002-000000000004', 'saude-intestinal-premium', 'Saúde Intestinal', 'Protocolo premium de 21 dias para restaurar o equilíbrio da microbiota, melhorar digestão e fortalecer o eixo intestino-cérebro.', 'Reconstruir a saúde intestinal com alimentação funcional, fibras prebióticas, probióticos naturais e hábitos que reduzem inflamação.', 'Plano estruturado em três semanas: eliminação de provocadores, introdução de alimentos funcionais e personalização da rotina intestinal.', 'intestinal', 'Saúde Intestinal', '21 dias', 'Intermediário', '["Digestão mais confortável","Menos inchaço abdominal","Evacuação regular","Mais energia após as refeições","Suporte à imunidade"]'::jsonb, '[{"title":"Semana 1","description":"Eliminação de provocadores e mapeamento de sintomas."},{"title":"Semana 2","description":"Introdução de prebióticos, probióticos e fibras."},{"title":"Semana 3","description":"Consolidação e cardápio personalizado."}]'::jsonb, true, false, 'Premium', 531, '/logo-saude-bem.png', '[{"type":"image","url":"/logo-saude-bem.png","alt":"Capa: Saúde Intestinal"},{"type":"heading","level":2,"text":"Objetivo"},{"type":"paragraph","text":"Reconstruir a saúde intestinal com alimentação funcional, fibras prebióticas, probióticos naturais e hábitos que reduzem inflamação."},{"type":"heading","level":2,"text":"Duração"},{"type":"paragraph","text":"21 dias · Nível Intermediário. Siga o roteiro diário com constância; ajustes finos são esperados conforme sua rotina."},{"type":"heading","level":2,"text":"Passo a passo diário"},{"type":"list","items":["Começar o dia com água morna e limão (se tolerado).","Incluir 25–30 g de fibras (vegetais, sementes, leguminosas).","Consumir 1 porção de alimento fermentado (iogurte, kefir, chucrute).","Mastigar bem e comer sem pressa (mínimo 20 min por refeição).","Evitar ultraprocessados e excesso de açúcar no dia.","Hidratar-se: meta de 30–35 ml/kg de peso.","Movimento pós-refeição: caminhada leve de 10 min.","Noite: chá digestivo (camomila, erva-doce ou gengibre)."],"ordered":true},{"type":"heading","level":2,"text":"Checklist diária"},{"type":"list","items":["Hidratação matinal","Meta de fibras atingida","Alimento fermentado","Refeições conscientes","Sem ultraprocessados","Água ao longo do dia","Movimento pós-refeição","Ritual noturno digestivo"]},{"type":"heading","level":2,"text":"Benefícios esperados"},{"type":"list","items":["Digestão mais confortável","Menos inchaço abdominal","Evacuação regular","Mais energia após as refeições","Suporte à imunidade"]},{"type":"heading","level":2,"text":"Continue no Clube Premium"},{"type":"paragraph","html":"<p>Este protocolo faz parte do <strong>Clube Saúde &amp; Bem Premium</strong>. Assine para acessar o passo a passo completo, checklist imprimível e acompanhamento na sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'Saúde Intestinal | Protocolo Premium Saúde & Bem', 'Protocolo premium de 21 dias para restaurar o equilíbrio da microbiota, melhorar digestão e fortalecer o eixo intestino-cérebro.', 'saude, intestinal, premium, intestinal, protocolo, premium, saúde e bem', '/logo-saude-bem.png', 'published');
insert into public.protocols (id, slug, title, description, objective, long_description, category, category_label, duration, level, benefits, steps, is_premium, featured, tag, participants, cover_image_url, content, seo_title, seo_description, seo_keywords, og_image_url, status) values ('71000002-0002-4002-8002-000000000005', 'habitos-saudaveis-30-dias', 'Hábitos Saudáveis 30 Dias', 'Desafio premium de 30 dias para instalar hábitos fundamentais de saúde: movimento, alimentação, sono, hidratação e mente.', 'Transformar comportamentos isolados em rotina sustentável com metas semanais progressivas e acompanhamento por checklist.', 'Um mês de micro-compromissos diários que constroem a base da sua jornada de saúde — ideal para quem quer recomeçar com estrutura.', 'bem-estar-geral', 'Bem-estar Geral', '30 dias', 'Iniciante', '["Rotina estruturada e repetível","Hábitos ancorados no dia a dia","Mais autoconfiança na jornada","Base para protocolos avançados","Sensação de progresso mensurável"]'::jsonb, '[{"title":"Semana 1","description":"Sono, água e movimento mínimo viável."},{"title":"Semanas 2–3","description":"Alimentação consciente e pausas digitais."},{"title":"Semana 4","description":"Consolidação, revisão e plano dos próximos 30 dias."}]'::jsonb, true, true, 'Premium', 568, '/logo-saude-bem.png', '[{"type":"image","url":"/logo-saude-bem.png","alt":"Capa: Hábitos Saudáveis 30 Dias"},{"type":"heading","level":2,"text":"Objetivo"},{"type":"paragraph","text":"Transformar comportamentos isolados em rotina sustentável com metas semanais progressivas e acompanhamento por checklist."},{"type":"heading","level":2,"text":"Duração"},{"type":"paragraph","text":"30 dias · Nível Iniciante. Siga o roteiro diário com constância; ajustes finos são esperados conforme sua rotina."},{"type":"heading","level":2,"text":"Passo a passo diário"},{"type":"list","items":["Acordar no horário definido e beber 1 copo de água.","10 min de movimento (caminhada, alongamento ou treino curto).","1 refeição ‘arco-íris’ (metade do prato com vegetais).","Pausa de 5 min sem tela a cada 2h de trabalho.","Registrar no checklist o hábito do dia (foco semanal).","2,5 L de água (ajustar ao peso e clima).","Desconectar telas 60 min antes de dormir.","Dormir no horário planejado (7–8 h de janela)."],"ordered":true},{"type":"heading","level":2,"text":"Checklist diária"},{"type":"list","items":["Despertar no horário","Movimento matinal","Prato com vegetais","Pausas sem tela","Checklist preenchido","Meta de hidratação","Desconexão noturna","Sono no horário"]},{"type":"heading","level":2,"text":"Benefícios esperados"},{"type":"list","items":["Rotina estruturada e repetível","Hábitos ancorados no dia a dia","Mais autoconfiança na jornada","Base para protocolos avançados","Sensação de progresso mensurável"]},{"type":"heading","level":2,"text":"Continue no Clube Premium"},{"type":"paragraph","html":"<p>Este protocolo faz parte do <strong>Clube Saúde &amp; Bem Premium</strong>. Assine para acessar o passo a passo completo, checklist imprimível e acompanhamento na sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'Hábitos Saudáveis 30 Dias | Protocolo Premium Saúde & Bem', 'Desafio premium de 30 dias para instalar hábitos fundamentais de saúde: movimento, alimentação, sono, hidratação e mente.', 'habitos, saudaveis, 30, dias, bem estar geral, protocolo, premium, saúde e bem', '/logo-saude-bem.png', 'published');
insert into public.protocols (id, slug, title, description, objective, long_description, category, category_label, duration, level, benefits, steps, is_premium, featured, tag, participants, cover_image_url, content, seo_title, seo_description, seo_keywords, og_image_url, status) values ('71000002-0002-4002-8002-000000000006', 'hidratacao-inteligente', 'Hidratação Inteligente', 'Protocolo de 10 dias para calcular sua meta personalizada, criar lembretes práticos e eliminar sinais de desidratação crônica.', 'Estabelecer uma rotina de hidratação baseada no seu peso, clima e nível de atividade — com estratégias para manter a consistência.', 'Vai além de ‘beber água’: inclui eletrólitos naturais, timing estratégico e sinais corporais para otimizar energia e função cognitiva.', 'nutricao', 'Hidratação', '10 dias', 'Iniciante', '["Mais energia e foco","Pele e digestão mais equilibradas","Menos dores de cabeça","Melhor performance no exercício","Hábito automático de hidratar"]'::jsonb, '[{"title":"Dias 1–3","description":"Cálculo da meta e âncoras matinais."},{"title":"Dias 4–7","description":"Lembretes, eletrólitos e ajuste fino."},{"title":"Dias 8–10","description":"Consolidação e manutenção de longo prazo."}]'::jsonb, true, false, 'Premium', 605, '/blog/categories/hidratacao.svg', '[{"type":"image","url":"/blog/categories/hidratacao.svg","alt":"Capa: Hidratação Inteligente"},{"type":"heading","level":2,"text":"Objetivo"},{"type":"paragraph","text":"Estabelecer uma rotina de hidratação baseada no seu peso, clima e nível de atividade — com estratégias para manter a consistência."},{"type":"heading","level":2,"text":"Duração"},{"type":"paragraph","text":"10 dias · Nível Iniciante. Siga o roteiro diário com constância; ajustes finos são esperados conforme sua rotina."},{"type":"heading","level":2,"text":"Passo a passo diário"},{"type":"list","items":["Calcular meta: 30–35 ml × peso (kg); anotar no app ou garrafa.","2 copos de água ao acordar (antes do café).","1 copo antes de cada refeição principal.","Garrafa visível na mesa de trabalho; refill de manhã e tarde.","Adicionar eletrólitos naturais em 1 copo (limão + pitada de sal).","Urina clara palha: usar como feedback visual.","Reduzir excesso de álcool e cafeína desidratante.","Revisar meta ao final do dia e ajustar se necessário."],"ordered":true},{"type":"heading","level":2,"text":"Checklist diária"},{"type":"list","items":["Meta calculada","Água ao acordar","Água pré-refeição","Garrafa à mão","Eletrólitos naturais","Feedback de urina","Moderação cafeína/álcool","Revisão noturna"]},{"type":"heading","level":2,"text":"Benefícios esperados"},{"type":"list","items":["Mais energia e foco","Pele e digestão mais equilibradas","Menos dores de cabeça","Melhor performance no exercício","Hábito automático de hidratar"]},{"type":"heading","level":2,"text":"Continue no Clube Premium"},{"type":"paragraph","html":"<p>Este protocolo faz parte do <strong>Clube Saúde &amp; Bem Premium</strong>. Assine para acessar o passo a passo completo, checklist imprimível e acompanhamento na sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'Hidratação Inteligente | Protocolo Premium Saúde & Bem', 'Protocolo de 10 dias para calcular sua meta personalizada, criar lembretes práticos e eliminar sinais de desidratação crônica.', 'hidratacao, inteligente, nutricao, protocolo, premium, saúde e bem', '/blog/categories/hidratacao.svg', 'published');
insert into public.protocols (id, slug, title, description, objective, long_description, category, category_label, duration, level, benefits, steps, is_premium, featured, tag, participants, cover_image_url, content, seo_title, seo_description, seo_keywords, og_image_url, status) values ('71000002-0002-4002-8002-000000000007', 'mobilidade-alongamento', 'Mobilidade e Alongamento', 'Programa premium de 14 dias para destravar articulações, reduzir rigidez e prevenir dores por sedentarismo — 15 min por dia.', 'Recuperar amplitude de movimento com sequências guiadas de mobilidade e alongamento para coluna, quadril, ombros e tornozelos.', 'Ideal para quem trabalha sentado: rotinas curtas, progressivas e sem equipamento, com foco em postura e liberação miofascial.', 'exercicios', 'Exercícios', '14 dias', 'Iniciante', '["Menos rigidez ao acordar","Melhor postura no dia a dia","Redução de dores lombares e cervicais","Mais amplitude nos treinos","Prevenção de lesões"]'::jsonb, '[{"title":"Dias 1–5","description":"Coluna e quadril — base da mobilidade."},{"title":"Dias 6–10","description":"Cadeia posterior e ombros."},{"title":"Dias 11–14","description":"Sequência completa personalizada."}]'::jsonb, true, false, 'Premium', 642, '/logo-saude-bem.png', '[{"type":"image","url":"/logo-saude-bem.png","alt":"Capa: Mobilidade e Alongamento"},{"type":"heading","level":2,"text":"Objetivo"},{"type":"paragraph","text":"Recuperar amplitude de movimento com sequências guiadas de mobilidade e alongamento para coluna, quadril, ombros e tornozelos."},{"type":"heading","level":2,"text":"Duração"},{"type":"paragraph","text":"14 dias · Nível Iniciante. Siga o roteiro diário com constância; ajustes finos são esperados conforme sua rotina."},{"type":"heading","level":2,"text":"Passo a passo diário"},{"type":"list","items":["Aquecimento: 2 min de movimento articular (pescoço, ombros, quadril).","Mobilidade de coluna: gato-vaca, rotações e extensões (3 min).","Quadril: alongamento flexor + agachamento profundo assistido (4 min).","Ombros e torácica: abertura em porta ou rotações (3 min).","Posterior de coxa e panturrilha: alongamentos estáticos 30 s cada (3 min).","Respiração diafragmática final: 1 min.","Registrar sensação de rigidez (0–10) no checklist.","Caminhada leve de 10 min se possível (complemento)."],"ordered":true},{"type":"heading","level":2,"text":"Checklist diária"},{"type":"list","items":["Aquecimento articular","Mobilidade de coluna","Liberação de quadril","Ombros e torácica","Alongamento posterior","Respiração final","Escala de rigidez","Caminhada complementar"]},{"type":"heading","level":2,"text":"Benefícios esperados"},{"type":"list","items":["Menos rigidez ao acordar","Melhor postura no dia a dia","Redução de dores lombares e cervicais","Mais amplitude nos treinos","Prevenção de lesões"]},{"type":"heading","level":2,"text":"Continue no Clube Premium"},{"type":"paragraph","html":"<p>Este protocolo faz parte do <strong>Clube Saúde &amp; Bem Premium</strong>. Assine para acessar o passo a passo completo, checklist imprimível e acompanhamento na sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'Mobilidade e Alongamento | Protocolo Premium Saúde & Bem', 'Programa premium de 14 dias para destravar articulações, reduzir rigidez e prevenir dores por sedentarismo — 15 min por dia.', 'mobilidade, alongamento, exercicios, protocolo, premium, saúde e bem', '/logo-saude-bem.png', 'published');
insert into public.protocols (id, slug, title, description, objective, long_description, category, category_label, duration, level, benefits, steps, is_premium, featured, tag, participants, cover_image_url, content, seo_title, seo_description, seo_keywords, og_image_url, status) values ('71000002-0002-4002-8002-000000000008', 'foco-produtividade', 'Foco e Produtividade', 'Protocolo de 14 dias para deep work, gestão de energia mental e eliminação de distrações — sem burnout.', 'Implementar blocos de foco, rituais de início/fim de trabalho e hábitos que maximizam output com menos horas e mais clareza.', 'Combina neurociência do foco com práticas de organização: ambiente, priorização, pausas estratégicas e desligar com qualidade.', 'mente', 'Mente', '14 dias', 'Intermediário', '["Mais trabalho profundo por dia","Menos procrastinação","Energia mental preservada","Fechamento consciente do expediente","Melhor equilíbrio vida-trabalho"]'::jsonb, '[{"title":"Dias 1–4","description":"Priorização e primeiro bloco de foco."},{"title":"Dias 5–10","description":"Ambiente, distrações e pausas."},{"title":"Dias 11–14","description":"Rotina personalizada de produtividade."}]'::jsonb, true, false, 'Premium', 679, '/logo-saude-bem.png', '[{"type":"image","url":"/logo-saude-bem.png","alt":"Capa: Foco e Produtividade"},{"type":"heading","level":2,"text":"Objetivo"},{"type":"paragraph","text":"Implementar blocos de foco, rituais de início/fim de trabalho e hábitos que maximizam output com menos horas e mais clareza."},{"type":"heading","level":2,"text":"Duração"},{"type":"paragraph","text":"14 dias · Nível Intermediário. Siga o roteiro diário com constância; ajustes finos são esperados conforme sua rotina."},{"type":"heading","level":2,"text":"Passo a passo diário"},{"type":"list","items":["Definir 1–3 prioridades do dia (máximo) na noite anterior ou ao acordar.","Ritual de início: 2 min de respiração + abrir só a tarefa principal.","Bloco 1: 90 min foco total (celular em outro cômodo).","Pausa 15 min: movimento + água, sem redes sociais.","Bloco 2: 60–90 min em tarefa secundária.","Revisão de meio-dia: ainda estou na prioridade certa?","Tarde: tarefas operacionais e e-mails em bloco único de 30 min.","Encerramento: listar feito/amanhã + desligar notificações."],"ordered":true},{"type":"heading","level":2,"text":"Checklist diária"},{"type":"list","items":["Prioridades definidas","Ritual de início","Bloco deep work 1","Pausa restaurativa","Bloco deep work 2","Checagem de foco","E-mails em bloco","Encerramento consciente"]},{"type":"heading","level":2,"text":"Benefícios esperados"},{"type":"list","items":["Mais trabalho profundo por dia","Menos procrastinação","Energia mental preservada","Fechamento consciente do expediente","Melhor equilíbrio vida-trabalho"]},{"type":"heading","level":2,"text":"Continue no Clube Premium"},{"type":"paragraph","html":"<p>Este protocolo faz parte do <strong>Clube Saúde &amp; Bem Premium</strong>. Assine para acessar o passo a passo completo, checklist imprimível e acompanhamento na sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'Foco e Produtividade | Protocolo Premium Saúde & Bem', 'Protocolo de 14 dias para deep work, gestão de energia mental e eliminação de distrações — sem burnout.', 'foco, produtividade, mente, protocolo, premium, saúde e bem', '/logo-saude-bem.png', 'published');
insert into public.protocols (id, slug, title, description, objective, long_description, category, category_label, duration, level, benefits, steps, is_premium, featured, tag, participants, cover_image_url, content, seo_title, seo_description, seo_keywords, og_image_url, status) values ('71000002-0002-4002-8002-000000000009', 'emagrecimento-saudavel', 'Emagrecimento Saudável', 'Protocolo premium de 28 dias para perda de gordura sustentável com foco em saúde metabólica, saciedade e preservação de massa magra.', 'Criar déficit calórico moderado com alimentação nutritiva, movimento progressivo e hábitos que evitam efeito sanfona.', 'Abordagem baseada em evidências: proteína adequada, fibras, força + cardio leve, sono e gestão do estresse para resultados duradouros.', 'alimentacao-saudavel', 'Emagrecimento', '28 dias', 'Intermediário', '["Perda de gordura gradual e sustentável","Mais saciedade nas refeições","Energia estável no processo","Preservação de massa muscular","Hábitos que permanecem após o protocolo"]'::jsonb, '[{"title":"Semana 1","description":"Baseline, proteína e registro alimentar."},{"title":"Semanas 2–3","description":"Déficit moderado, movimento e força."},{"title":"Semana 4","description":"Ajuste fino e plano de manutenção."}]'::jsonb, true, false, 'Premium', 716, '/blog/categories/emagrecimento.svg', '[{"type":"image","url":"/blog/categories/emagrecimento.svg","alt":"Capa: Emagrecimento Saudável"},{"type":"heading","level":2,"text":"Objetivo"},{"type":"paragraph","text":"Criar déficit calórico moderado com alimentação nutritiva, movimento progressivo e hábitos que evitam efeito sanfona."},{"type":"heading","level":2,"text":"Duração"},{"type":"paragraph","text":"28 dias · Nível Intermediário. Siga o roteiro diário com constância; ajustes finos são esperados conforme sua rotina."},{"type":"heading","level":2,"text":"Passo a passo diário"},{"type":"list","items":["Café da manhã proteico (mín. 25 g proteína).","Vegetais em 2 refeições (volume e fibras).","Água: meta diária personalizada.","Movimento: 8–10 mil passos ou 30 min cardio leve.","2x/semana: treino de força (corpo inteiro ou superior/inferior).","Jantar mais leve; última refeição 3h antes de dormir.","Sono 7–8 h (prioridade metabólica).","Registrar refeições ou foto do prato (consciência alimentar)."],"ordered":true},{"type":"heading","level":2,"text":"Checklist diária"},{"type":"list","items":["Proteína no café da manhã","Vegetais no dia","Hidratação","Passos ou cardio","Força (se dia programado)","Jantar leve e cedo","Sono adequado","Registro alimentar"]},{"type":"heading","level":2,"text":"Benefícios esperados"},{"type":"list","items":["Perda de gordura gradual e sustentável","Mais saciedade nas refeições","Energia estável no processo","Preservação de massa muscular","Hábitos que permanecem após o protocolo"]},{"type":"heading","level":2,"text":"Continue no Clube Premium"},{"type":"paragraph","html":"<p>Este protocolo faz parte do <strong>Clube Saúde &amp; Bem Premium</strong>. Assine para acessar o passo a passo completo, checklist imprimível e acompanhamento na sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'Emagrecimento Saudável | Protocolo Premium Saúde & Bem', 'Protocolo premium de 28 dias para perda de gordura sustentável com foco em saúde metabólica, saciedade e preservação de massa magra.', 'emagrecimento, saudavel, alimentacao saudavel, protocolo, premium, saúde e bem', '/blog/categories/emagrecimento.svg', 'published');
insert into public.protocols (id, slug, title, description, objective, long_description, category, category_label, duration, level, benefits, steps, is_premium, featured, tag, participants, cover_image_url, content, seo_title, seo_description, seo_keywords, og_image_url, status) values ('71000002-0002-4002-8002-000000000010', 'longevidade-premium', 'Longevidade', 'Protocolo avançado de 90 dias com os pilares da ciência do envelhecimento saudável: nutrição, movimento, sono, estresse e conexão social.', 'Implementar hábitos de longevidade baseados em evidências para envelhecer com vitalidade, independência e biomarcadores otimizados.', 'Programa integrado em três fases: avaliação inicial, implementação dos cinco pilares e otimização personalizada para manutenção de longo prazo.', 'longevidade', 'Longevidade', '90 dias', 'Avançado', '["Marcadores de saúde mais favoráveis","Mais energia e resiliência","Prevenção de doenças crônicas","Massa muscular e óssea preservadas","Qualidade de vida na maturidade"]'::jsonb, '[{"title":"Fase 1 (30 dias)","description":"Baseline, exames e fundação dos pilares."},{"title":"Fase 2 (30 dias)","description":"Implementação completa e ajustes."},{"title":"Fase 3 (30 dias)","description":"Otimização, manutenção e próximos passos."}]'::jsonb, true, false, 'Premium', 753, '/blog/categories/longevidade.svg', '[{"type":"image","url":"/blog/categories/longevidade.svg","alt":"Capa: Longevidade"},{"type":"heading","level":2,"text":"Objetivo"},{"type":"paragraph","text":"Implementar hábitos de longevidade baseados em evidências para envelhecer com vitalidade, independência e biomarcadores otimizados."},{"type":"heading","level":2,"text":"Duração"},{"type":"paragraph","text":"90 dias · Nível Avançado. Siga o roteiro diário com constância; ajustes finos são esperados conforme sua rotina."},{"type":"heading","level":2,"text":"Passo a passo diário"},{"type":"list","items":["Alimentação tipo mediterrânea: vegetais, azeite, peixe, leguminosas.","150 min/semana de cardio moderado + 2x força (distribuir na semana).","Sono 7–8 h com horário consistente.","Exposição solar segura 15 min + vitamina D se indicado.","Prática de regulação do estresse (10 min/dia).","Conexão social: 1 contato significativo por dia.","Evitar fumar e limitar álcool (máx. 1 dose ocasional).","Revisão semanal de progresso e biomarcadores (quando disponível)."],"ordered":true},{"type":"heading","level":2,"text":"Checklist diária"},{"type":"list","items":["Prato mediterrâneo","Movimento do dia","Sono na janela","Luz solar segura","Prática anti-estresse","Conexão social","Hábitos de risco evitados","Revisão semanal"]},{"type":"heading","level":2,"text":"Benefícios esperados"},{"type":"list","items":["Marcadores de saúde mais favoráveis","Mais energia e resiliência","Prevenção de doenças crônicas","Massa muscular e óssea preservadas","Qualidade de vida na maturidade"]},{"type":"heading","level":2,"text":"Continue no Clube Premium"},{"type":"paragraph","html":"<p>Este protocolo faz parte do <strong>Clube Saúde &amp; Bem Premium</strong>. Assine para acessar o passo a passo completo, checklist imprimível e acompanhamento na sua jornada.</p><p><a href=\"/clube\">Conhecer o Clube Premium</a> · <a href=\"/assinar\">Ver planos</a></p>"}]'::jsonb, 'Longevidade | Protocolo Premium Saúde & Bem', 'Protocolo avançado de 90 dias com os pilares da ciência do envelhecimento saudável: nutrição, movimento, sono, estresse e conexão social.', 'longevidade, premium, longevidade, protocolo, premium, saúde e bem', '/blog/categories/longevidade.svg', 'published');
insert into public.library_items (id, slug, title, description, long_description, category, category_label, item_type, tier, is_premium, image_url, estimated_read_time, featured, assets, seo_title, seo_description, seo_keywords, og_image_url, status) values ('71000004-0004-4004-8004-000000000001', 'sono-restaurador', 'Sono Restaurador', 'Protocolo premium de 21 dias para regular o ritmo circadiano, aprofundar o sono e acordar com energia real — sem depender de estimulantes.', 'Um plano progressivo que combina higiene do sono, gestão de luz e temperatura, alimentação estratégica e técnicas de relaxamento para noites consistentemente reparadoras.', 'sono', 'Sono', 'protocolo', 'premium', true, '/blog/categories/sono.svg', '21 dias', true, '{"protocolSlug":"sono-restaurador"}'::jsonb, 'Sono Restaurador | Biblioteca Saúde & Bem', 'Protocolo premium de 21 dias para regular o ritmo circadiano, aprofundar o sono e acordar com energia real — sem depender de estimulantes.', 'sono, restaurador, sono, protocolo, premium, saúde e bem', '/blog/categories/sono.svg', 'published');
